def metric(data: pd.DataFrame) -> float:
    import numpy as np

    val = np.array([0.9, 0.8, 0.7, 0.6, 0.5])

    wadd_match = 0
    n_ties = 0

    for _, row in data.iterrows():
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])

        a_wins = np.sum(a > b)
        b_wins = np.sum(b > a)

        if a_wins == b_wins:
            wadd_a = np.sum(a * val)
            wadd_b = np.sum(b * val)

            if wadd_a > wadd_b:
                expected = 0
            elif wadd_b > wadd_a:
                expected = 1
            else:
                continue

            if row['response'] == expected:
                wadd_match += 1
            n_ties += 1

    if n_ties == 0:
        return 0.5
    return wadd_match / n_ties

